_PASS = {"farmer": ["PASS"], "hands": [], "market": []}


def majkel_tape_agent(observation, configuration=None):
    try:
        step = int(observation.get("step", 0))
        return _TAPE[step] if 0 <= step < len(_TAPE) else _PASS
    except Exception:
        return _PASS
